"""
Builds a single HTML file visualizing history.json as column charts, using
Highcharts (https://www.highcharts.com/). Highcharts itself is downloaded
once to highcharts.js next to this file (cached there afterwards), and the
report references that local copy -- so after the first download, viewing
and regenerating reports never needs a network connection.

Layout mirrors `run.py report`: one section per benchmark, one small chart
per position within that benchmark's output (matching how report aligns
values positionally, since the same benchmark script always prints the same
sequence of labeled/unlabeled numbers). Each chart has one bar per recorded
run, in chronological order.

Design notes:
- Bars, not lines: each run is a discrete, unevenly-spaced snapshot, and some
  executables (e.g. a one-off reference build) may only ever have a single
  run, so a line would either be invisible or imply a trend that isn't there.
- Every executable gets one consistent color, assigned once globally and
  reused for the legend and every chart's bars. Each bar's x-axis category is
  "sha (executable)", not just the sha, since two different executables built
  from the same commit share a SHA -- labeling by SHA alone would put them at
  the same x-axis position, stacking them on top of each other.
- The y-axis is zoomed to the actual data range (with headroom), not forced
  to include zero, so small-but-real differences between runs are visible.
  Each bar still gets an exact-value data label, so the zoomed axis can't be
  misread as bigger/smaller than it really is.
- Correctness-check positions (see semantics.py -- tree depths, checksums,
  etc: deterministic program-behavior values, not performance numbers) are
  not charted at all. They're validated against the official jlox reference
  instead (see correctness.py); mismatches show up as a warning banner here
  and as errors from `run.py run`/`report`/`history`.
- A run whose interpreter crashed/timed out on a benchmark (block["error"]
  set) still gets a slot on every remaining chart for that benchmark, drawn
  as a full-height "ERROR" column rather than being silently skipped -- so
  you can see *when* something broke relative to your other runs.
- zoo_batch.lox's throughput positions are marked "(higher is better)".
- The report explicitly forces a light Highcharts theme (via Highcharts.
  setOptions and a `color-scheme: light` meta tag/CSS), since newer
  Highcharts versions can otherwise follow the OS/browser's dark-mode
  preference automatically.
"""

import html
import json
import os
import subprocess
from pathlib import Path

from semantics import is_check_entry, is_higher_better
from correctness import build_jlox_reference, find_correctness_errors, format_mismatch

HIGHCHARTS_PATH = Path(__file__).resolve().parent / "highcharts.js"
HIGHCHARTS_URL = "https://code.highcharts.com/highcharts.js"

PALETTE = [
    "#1f77b4", "#d62728", "#2ca02c", "#9467bd", "#ff7f0e",
    "#17becf", "#e377c2", "#8c564b", "#bcbd22", "#7f7f7f",
]
ERROR_COLOR = "#b00020"


def _ensure_highcharts():
    """Downloads highcharts.js next to this file if it isn't already there,
    so the generated report can reference a local copy instead of the CDN --
    once downloaded, viewing reports never needs a network connection again.
    Highcharts' CDN rejects requests with no Referer header, hence --header.
    """
    if HIGHCHARTS_PATH.exists() and HIGHCHARTS_PATH.stat().st_size > 0:
        return True
    print(f"Downloading Highcharts to {HIGHCHARTS_PATH} (one-time; cached after this) ...")
    cmd = [
        "wget",
        "--header=Referer: https://www.highcharts.com/",
        "-O", str(HIGHCHARTS_PATH),
        HIGHCHARTS_URL,
    ]
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30)
    except (OSError, subprocess.SubprocessError) as e:
        print(f"  couldn't run wget: {e}")
        result = None

    ok = result is not None and result.returncode == 0 and HIGHCHARTS_PATH.exists() \
        and HIGHCHARTS_PATH.stat().st_size > 0
    if not ok:
        if HIGHCHARTS_PATH.exists():
            HIGHCHARTS_PATH.unlink()  # don't cache a partial/empty file as if it succeeded
        print(f"  download failed. The report will still reference {HIGHCHARTS_PATH.name}, "
              f"so charts won't render until you fetch it, e.g.:\n"
              f'    wget --header="Referer: https://www.highcharts.com/" '
              f"-O {HIGHCHARTS_PATH} {HIGHCHARTS_URL}")
    return ok


def _series_display_name(exe_path):
    p = Path(exe_path)
    if p.parent.name:
        return f"{p.parent.name}/{p.name}"
    return p.name


def _bar_label(run):
    return run.get("git_sha") or run["id"]


def _collect(history):
    """Returns {benchmark: {index: {"label": str, "points": [(x, run, value_or_None, error_or_None)]}}}

    value is None (and error is the message) for a run whose interpreter
    errored on this benchmark -- it still gets a slot on every remaining
    (non-check) chart position for that benchmark, so failures are visible
    rather than silently vanishing from the timeline.
    """
    runs = history["runs"]

    # How many entries does a *successful* run of this benchmark produce?
    max_len = {}
    for run in runs:
        for bench, block in run["benchmarks"].items():
            if block["error"]:
                continue
            max_len[bench] = max(max_len.get(bench, 0), len(block["entries"]))

    structure = {}
    for x, run in enumerate(runs):
        for bench, block in run["benchmarks"].items():
            n = max_len.get(bench, 0)
            if n == 0:
                continue  # no successful run of this benchmark exists anywhere
            structure.setdefault(bench, {})
            if block["error"]:
                for i in range(n):
                    if is_check_entry(bench, i, None):
                        continue
                    slot = structure[bench].setdefault(i, {"label": None, "points": []})
                    slot["points"].append((x, run, None, block["error"]))
                continue
            for i, entry in enumerate(block["entries"]):
                if is_check_entry(bench, i, entry["label"]):
                    continue
                slot = structure[bench].setdefault(i, {"label": None, "points": []})
                if entry["label"] and not slot["label"]:
                    slot["label"] = entry["label"]
                slot["points"].append((x, run, entry["value"], None))
    return structure


def _axis_range(vals):
    """Zoom to the data range (with headroom) rather than forcing a zero
    baseline, so small real differences between runs stay visible. Keeps
    zero in range if the data actually straddles it, since that's real sign
    information, not just headroom."""
    raw_min, raw_max = min(vals), max(vals)
    if raw_min == raw_max:
        pad = abs(raw_min) * 0.1 if raw_min != 0 else 1.0
        return raw_min - pad, raw_max + pad
    span = raw_max - raw_min
    pad = span * 0.15
    y_min, y_max = raw_min - pad, raw_max + pad
    if raw_min > 0 > y_min:
        y_min = 0.0  # don't manufacture a fake negative just from padding
    if raw_max < 0 < y_max:
        y_max = 0.0
    return y_min, y_max


def _chart_spec(bench, index, title, points, chart_id, exe_colors):
    points = sorted(points, key=lambda t: t[0])

    vals = [v for (_, _, v, err) in points if err is None]
    if vals:
        y_min, y_max = _axis_range(vals)
    else:
        y_min, y_max = 0.0, 1.0  # every run of this benchmark errored

    full_title = title
    if is_higher_better(bench, index):
        full_title += "  (higher is better)"

    data = []
    categories = []
    for x, run, v, err in points:
        exe_name = _series_display_name(run["executable"])
        sha = run.get("git_sha") or "n/a"
        label = run.get("label") or ""
        categories.append(f"{_bar_label(run)} ({exe_name})")
        if err is not None:
            tooltip = f"{exe_name}\n{run['timestamp']}\nsha={sha}\nERROR: {err}"
            if label:
                tooltip += f"\n{label}"
            data.append({
                "y": y_max,
                "color": ERROR_COLOR,
                "custom": {"tooltip": tooltip, "isError": True},
            })
        else:
            tooltip = f"{exe_name}\n{run['timestamp']}\nsha={sha}\nvalue={v:.6g}"
            if label:
                tooltip += f"\n{label}"
            data.append({
                "y": v,
                "color": exe_colors.get(run["executable"], "#999"),
                "custom": {"tooltip": tooltip, "isError": False},
            })

    return {
        "id": chart_id,
        "title": full_title,
        "yMin": y_min,
        "yMax": y_max,
        "benchLabel": title,
        "categories": categories,
        "data": data,
    }


def build_html(history, output_path):
    structure = _collect(history)

    reference = build_jlox_reference(history)
    correctness_errors = find_correctness_errors(history, reference=reference)

    highcharts_ok = _ensure_highcharts()
    highcharts_src = os.path.relpath(HIGHCHARTS_PATH, start=Path(output_path).resolve().parent)

    if not structure and not correctness_errors:
        return _wrap_html("<p>No successful runs recorded yet. Use 'run' to record some first.</p>",
                           [], [], highcharts_src, highcharts_ok)

    exe_paths = sorted({run["executable"] for run in history["runs"]})
    exe_colors = {exe: PALETTE[i % len(PALETTE)] for i, exe in enumerate(exe_paths)}

    legend_items = "".join(
        f'<span class="legend-item"><span class="swatch" style="background:{exe_colors[e]}"></span>'
        f'{html.escape(_series_display_name(e))}</span>'
        for e in exe_paths
    )
    legend_items += (
        '<span class="legend-item"><span class="swatch" style="background:'
        f'{ERROR_COLOR}"></span>interpreter error (see tooltip)</span>'
    )

    sections_html = []
    chart_specs = []
    for bench in sorted(structure):
        container_divs = []
        for idx in sorted(structure[bench]):
            slot = structure[bench][idx]
            title = slot["label"] or f"#{idx}"
            chart_id = f"chart-{bench}-{idx}".replace(".", "_").replace(" ", "_")
            spec = _chart_spec(bench, idx, title, slot["points"], chart_id, exe_colors)
            chart_specs.append(spec)
            container_divs.append(f'<div class="chart-wrap"><div id="{chart_id}" class="chart"></div></div>')
        if container_divs:
            sections_html.append(
                f'<section><h2>{html.escape(bench)}</h2>'
                f'<div class="chart-grid">{"".join(container_divs)}</div></section>'
            )

    body = f'<div class="legend">{legend_items}</div>' + "\n".join(sections_html)
    return _wrap_html(body, chart_specs, correctness_errors, highcharts_src, highcharts_ok,
                       has_reference=bool(reference))


def _wrap_html(body, chart_specs, correctness_errors, highcharts_src, highcharts_ok, has_reference=True):
    warning_html = ""
    if not highcharts_ok:
        warning_html += (
            f'<div class="warning">Couldn\'t fetch <code>highcharts.js</code> automatically -- '
            f"charts below won't render until it's downloaded to "
            f"<code>{html.escape(str(HIGHCHARTS_PATH))}</code>. See the terminal output from "
            "the command that generated this report for the exact command to run.</div>"
        )
    if not has_reference:
        warning_html += (
            '<div class="warning">No run of an executable named <code>jlox</code> has been '
            "recorded yet, so correctness-check values (tree depths, checksums, etc.) can't be "
            "verified. Charts below only ever show real performance metrics, though -- "
            "correctness-check numbers are never charted.</div>"
        )
    elif correctness_errors:
        items = "".join(
            f'<li>[{html.escape(e["run_id"])}] {html.escape(Path(e["executable"]).name)} '
            f'&mdash; {html.escape(e["benchmark"])} \'{html.escape(e["label"])}\': '
            f'{html.escape(format_mismatch(e))}</li>'
            for e in correctness_errors
        )
        warning_html += (
            '<div class="warning"><strong>Correctness check failures</strong> '
            "(disagree with the recorded jlox reference):<ul>" + items + "</ul></div>"
        )

    charts_json = json.dumps(chart_specs)

    return f"""<!DOCTYPE html>
<!--
    This file was generated automatically by run.py's `plot` command (itself
    an AI-generated tool -- see run.py/plot.py). Do not hand-edit; it will be
    overwritten the next time you run `python3 run.py plot` (or `run`).
-->
<html>
<head>
<meta charset="utf-8">
<meta name="color-scheme" content="light">
<title>loxbench report</title>
<script src="{html.escape(highcharts_src)}"></script>
<style>
  :root {{ color-scheme: light; }}
  body {{ font-family: -apple-system, Helvetica, Arial, sans-serif; margin: 24px; color: #1a1a1a; background: #fafafa; }}
  h1 {{ margin-bottom: 4px; }}
  h2 {{ margin-top: 32px; border-bottom: 1px solid #ddd; padding-bottom: 4px; }}
  .legend {{ margin: 12px 0 24px; }}
  .legend-item {{ margin-right: 18px; font-size: 14px; }}
  .swatch {{ display: inline-block; width: 12px; height: 12px; border-radius: 2px; margin-right: 6px; vertical-align: middle; }}
  .chart-grid {{ display: flex; flex-wrap: wrap; gap: 12px; }}
  .chart-wrap {{ background: white; border: 1px solid #e0e0e0; border-radius: 6px; padding: 4px; }}
  .chart {{ width: 420px; height: 240px; }}
  .warning {{ background: #fff3f0; border: 1px solid #f3c2c2; border-radius: 6px;
              padding: 12px 16px; margin: 16px 0; font-size: 14px; }}
  .warning ul {{ margin: 6px 0 0; padding-left: 20px; }}
</style>
</head>
<body>
<h1>loxbench report</h1>
<p>One chart per number position within each benchmark's output. Each bar is one
recorded run, in chronological order, colored by executable (see legend) --
hover a bar for its full timestamp, git SHA, run label, and exact value. The Y
axis is zoomed to the actual data range for each chart (not forced to start at
zero) so small real differences between runs stay visible; the data label on
each bar tells you the true magnitude regardless of the zoom. Correctness-check
values (tree depths, checksums) aren't charted -- they're validated against the
official jlox reference instead. A run whose interpreter errored on a benchmark
shows up as a full-height "ERROR" column at its point in time rather than
vanishing from the chart. Bars are labeled "sha (executable)" rather than just
"sha", since two different executables built from the same commit share a SHA
and would otherwise land on the same x-axis position and hide each other.</p>
{warning_html}
{body}
<script>
// Force a light theme explicitly -- newer Highcharts versions can otherwise
// pick up an OS/browser dark-mode preference automatically, which is not
// what we want here.
Highcharts.setOptions({{
  chart: {{ backgroundColor: '#ffffff', style: {{ color: '#333333' }} }},
  title: {{ style: {{ color: '#333333' }} }},
  xAxis: {{
    lineColor: '#ccd6eb', tickColor: '#ccd6eb',
    labels: {{ style: {{ color: '#666666' }} }}
  }},
  yAxis: {{
    gridLineColor: '#e6e6e6', lineColor: '#ccd6eb', tickColor: '#ccd6eb',
    labels: {{ style: {{ color: '#666666' }} }}
  }},
  legend: {{ itemStyle: {{ color: '#333333' }} }},
  tooltip: {{ backgroundColor: '#ffffff', style: {{ color: '#333333' }} }}
}});

function loxTooltipFormatter() {{
  return this.point.custom.tooltip.replace(/\\n/g, '<br>');
}}
function loxDataLabelFormatter() {{
  return this.point.custom.isError ? 'ERROR' : Highcharts.numberFormat(this.y, 4);
}}
const loxCharts = {charts_json};
loxCharts.forEach(function(spec) {{
  Highcharts.chart(spec.id, {{
    chart: {{ type: 'column', height: 240 }},
    title: {{ text: spec.title, style: {{ fontSize: '12px' }} }},
    xAxis: {{
      categories: spec.categories,
      labels: {{ rotation: -40, style: {{ fontSize: '9px' }} }}
    }},
    yAxis: {{ min: spec.yMin, max: spec.yMax, title: {{ text: null }} }},
    legend: {{ enabled: false }},
    credits: {{ enabled: false }},
    plotOptions: {{
      column: {{
        threshold: spec.yMin,
        borderWidth: 0,
        dataLabels: {{ enabled: true, formatter: loxDataLabelFormatter, style: {{ fontSize: '9px' }} }}
      }}
    }},
    tooltip: {{ useHTML: true, formatter: loxTooltipFormatter }},
    series: [{{ name: spec.benchLabel, data: spec.data }}]
  }});
}});
</script>
</body>
</html>
"""


def write_report(history, output_path):
    html_text = build_html(history, output_path)
    Path(output_path).write_text(html_text)
    return output_path
